python - <<'EOF'
import doctest, sys, warnings, pkgutil, importlib
sys.path.insert(0, '.')
warnings.filterwarnings('ignore')
import stingray
skip = {'stingray.utils', 'stingray.pulse', 'stingray.deadtime'}
results = {}
for m in pkgutil.walk_packages(stingray.__path__, 'stingray.'):
    name = m.name
    if any(name == s or name.startswith(s + '.') for s in skip):
        continue
    try:
        mod = importlib.import_module(name)
    except Exception as e:
        results[name] = ('IMPORT_FAIL', str(e))
        continue
    try:
        r = doctest.testmod(mod, verbose=False, optionflags=doctest.ELLIPSIS)
    except Exception as e:
        results[name] = ('RUN_FAIL', repr(e))
        continue
    if r.failed:
        results[name] = r
print('failures:', len(results))
for name, r in results.items():
    print(name, r)
EOF
